function uncover(board: string[][], click: number[]): string[][] {
  const R = board.length, C = board[0].length;
  const [cr, cc] = click;
  if (board[cr][cc] === "M") { board[cr][cc] = "X"; return board; }
  const queue: number[][] = [[cr, cc]];
  for (let h = 0; h < queue.length; h++) {
    const [r, c] = queue[h];
    if (board[r][c] !== "H") continue;
    let mines = 0;
    for (let dr = -1; dr <= 1; dr++)
      for (let dc = -1; dc <= 1; dc++) {
        const nr = r + dr, nc = c + dc;
        if (nr >= 0 && nr < R && nc >= 0 && nc < C && board[nr][nc] === "M") mines++;
      }
    if (mines > 0) { board[r][c] = String(mines); continue; }
    board[r][c] = "_";
    for (let dr = -1; dr <= 1; dr++)
      for (let dc = -1; dc <= 1; dc++) {
        const nr = r + dr, nc = c + dc;
        if (nr >= 0 && nr < R && nc >= 0 && nc < C && board[nr][nc] === "H") queue.push([nr, nc]);
      }
  }
  return board;
}

