function uncover(board: string[][], click: number[]): string[][] {
  const R = board.length, C = board[0].length;
  if (board[click[0]][click[1]] === "M") { board[click[0]][click[1]] = "X"; return board; }
  const stack = [click[0] * C + click[1]];
  while (stack.length) {
    const id = stack.pop()!, r = Math.floor(id / C), c = id % C;
    if (board[r][c] !== "H") continue;
    const next: number[] = [];
    let mines = 0;
    for (let nr = Math.max(0, r - 1); nr <= Math.min(R - 1, r + 1); nr++)
      for (let nc = Math.max(0, c - 1); nc <= Math.min(C - 1, c + 1); nc++) {
        if (board[nr][nc] === "M") mines++;
        else if (board[nr][nc] === "H") next.push(nr * C + nc);
      }
    if (mines > 0) board[r][c] = String(mines);
    else { board[r][c] = "_"; stack.push(...next); }
  }
  return board;
}

