class Solution:
    def uncover(self, board: List[List[str]], click: List[int]) -> List[List[str]]:
        R, C = len(board), len(board[0])
        if board[click[0]][click[1]] == "M":
            board[click[0]][click[1]] = "X"
            return board
        stack = [tuple(click)]
        while stack:
            r, c = stack.pop()
            if board[r][c] != "H":
                continue
            mines, nxt = 0, []
            for nr in range(max(0, r - 1), min(R, r + 2)):
                for nc in range(max(0, c - 1), min(C, c + 2)):
                    if board[nr][nc] == "M":
                        mines += 1
                    elif board[nr][nc] == "H":
                        nxt.append((nr, nc))
            if mines:
                board[r][c] = str(mines)
            else:
                board[r][c] = "_"
                stack.extend(nxt)
        return board

